/* ============================================
   APP SIDEBAR — collapsible navigation
   Collapsed: 64px icon-only rail
   Expanded: 280px with labels, accordion, profile
   ============================================ */

/* ============================================
   WRAPPER
   ============================================ */
.ds-app-sidebar {
  position: fixed;
  top: 0;
  left: 0;
  z-index: 100;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  height: 100vh;
  width: 64px;
  padding: var(--padding-500) 0;
  /* The vertical padding sits inside the viewport height; content-box
     sizing ran the rail 40px past the bottom and clipped the profile. */
  box-sizing: border-box;
  background-color: var(--color-bg-page-primary);
  /* The logo mark draws in currentColor; without a colour of its own the
     rail inherited the host's, and the mark vanished on a dark host. */
  color: var(--color-text-primary);
  overflow: hidden;
  transition: width var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-app-sidebar--expanded {
  width: 280px;
}

/* ============================================
   FLOATING VARIANT — the rail as a glass card
   inset from the viewport edges (the same
   recipe as the site chat panel)
   ============================================ */
.ds-app-sidebar--floating {
  top: var(--ds-sidebar-float-inset, 20px);
  left: var(--ds-sidebar-float-inset, 20px);
  height: calc(100dvh - var(--ds-sidebar-float-inset, 20px) * 2);
  background-color: var(--color-bg-glass);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  box-shadow: var(--shadow-floating);
  /* The glass token is deliberately translucent; this blur is what keeps
     content behind the rail readable through it. */
  backdrop-filter: blur(24px);
}

/* ============================================
   TOP SECTION — logo + nav
   ============================================ */
.ds-app-sidebar__top {
  display: flex;
  flex-direction: column;
  gap: var(--gap-1000);
  overflow-y: auto;
  overflow-x: hidden;
  flex: 1;
  min-height: 0;
}

/* ============================================
   LOGO ROW
   ============================================ */
.ds-app-sidebar__logo {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 24px;
  padding: 0 var(--padding-500);
  flex-shrink: 0;
}

/* Expand/collapse choreography, here and on every row below: the rail's
   clipping width and the text's opacity fade carry the whole transition.
   Inner layout stays constant - text keeps its natural width with
   min-width: 0 so it truncates under the sweeping rail instead of holding
   rows at full width (width: 0 to auto cannot interpolate, and a gap that
   snaps mid-glide reads as a bounce). */
.ds-app-sidebar__logo-inner {
  display: flex;
  align-items: center;
  gap: var(--gap-500);
  min-width: 0;
}

.ds-app-sidebar__logo-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
}

.ds-app-sidebar__logo-text {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
  white-space: nowrap;
  min-width: 0;
  flex-shrink: 1;
  overflow: hidden;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-app-sidebar--expanded .ds-app-sidebar__logo-text {
  opacity: 1;
}

.ds-app-sidebar__toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 0;
  height: 24px;
  flex-shrink: 0;
  background: none;
  border: none;
  color: var(--color-icon-primary);
  cursor: pointer;
  padding: 0;
  overflow: hidden;
  opacity: 0;
  /* Both widths are explicit (0 and 24px), so the width glides too. */
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard), width var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-app-sidebar--expanded .ds-app-sidebar__toggle {
  width: 24px;
  opacity: 1;
}

.ds-app-sidebar__toggle .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard);
}

/* ============================================
   NAV GROUP
   ============================================ */
.ds-app-sidebar__nav {
  display: flex;
  flex-direction: column;
  gap: var(--gap-100);
  flex-shrink: 0;
  /* Stretch in both states: rows fill the rail and the collapsed icon is
     centred by the row's own padding, so alignment never snaps. */
  align-items: stretch;
}

/* Category label — only visible when expanded */
.ds-app-sidebar__category {
  padding: 0 var(--padding-500);
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  color: var(--color-text-tertiary);
  white-space: nowrap;
  opacity: 0;
  height: 0;
  overflow: hidden;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard), height var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-app-sidebar--expanded .ds-app-sidebar__category {
  opacity: 1;
  height: 20px;
}

/* ============================================
   NAV BUTTON
   ============================================ */
.ds-app-sidebar__btn {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 40px;
  min-width: 0;
  /* The same inset in both states: in the collapsed 64px rail the 12px
     margins leave a 40px row, so the hover pill is a perfect circle clear
     of the rail edges, with the icon centred (12 + 8 + 24 + 8 + 12 = 64);
     expanded, these are the pill's edge inset. Nothing to transition. */
  margin: 0 var(--padding-300);
  padding: var(--padding-200);
  border-radius: var(--radius-pill);
  background: transparent;
  border: none;
  color: var(--color-text-primary);
  cursor: pointer;
  overflow: hidden;
  text-align: left;
  /* The row renders as an <a> when the item carries an href. */
  text-decoration: none;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard), padding var(--motion-duration-slow) var(--motion-ease-emphasized), margin var(--motion-duration-slow) var(--motion-ease-emphasized);
}

/* Inset via margin + reduced padding (12 + 8 = the 20px the label sat at
   before), so the pill floats off the rail edges while the icon and label
   keep their exact x-positions against the category labels above. */

.ds-app-sidebar__btn:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-app-sidebar__btn--active {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-app-sidebar__btn-left {
  display: flex;
  align-items: center;
  gap: var(--gap-200);
  min-width: 0;
}

.ds-app-sidebar__btn-icon {
  --icon-size: var(--icon-size-600);
  color: var(--color-icon-primary);
  flex-shrink: 0;
}

/* A generated avatar in the icon seat: a block-level sprite, so the seat
   lays it out as a box rather than on the text baseline. */
.ds-app-sidebar__btn-icon--avatar {
  display: inline-flex;
}

.ds-app-sidebar__btn-label {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
  white-space: nowrap;
  min-width: 0;
  flex-shrink: 1;
  overflow: hidden;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-app-sidebar--expanded .ds-app-sidebar__btn-label {
  opacity: 1;
}

.ds-app-sidebar__btn-badge {
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-paragraph-sm-emphasis-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-secondary);
  background-color: var(--color-bg-container-tertiary);
  border-radius: var(--radius-pill);
  padding: var(--padding-050) var(--padding-200);
  min-width: 0;
  flex-shrink: 1;
  overflow: hidden;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-app-sidebar--expanded .ds-app-sidebar__btn-badge {
  opacity: 1;
}

.ds-app-sidebar__btn-chevron {
  font-size: 24px;
  color: var(--color-icon-secondary);
  min-width: 0;
  flex-shrink: 1;
  overflow: hidden;
  transition: transform var(--motion-duration-slow) var(--motion-ease-standard), opacity var(--motion-duration-base) var(--motion-ease-standard);
  opacity: 0;
}

.ds-app-sidebar--expanded .ds-app-sidebar__btn-chevron {
  opacity: 1;
}

.ds-app-sidebar__btn-chevron--open {
  transform: rotate(90deg);
}

/* ============================================
   SUB-ITEMS (accordion children)
   ============================================ */
.ds-app-sidebar__sub-items {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  max-height: 0;
  transition: max-height var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-app-sidebar__sub-items--open {
  max-height: 500px;
}

.ds-app-sidebar__sub-item {
  display: flex;
  align-items: flex-start;
  height: 40px;
}

.ds-app-sidebar__sub-line {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 44px;
  height: 100%;
  flex-shrink: 0;
  padding-left: 16px;
}

.ds-app-sidebar__sub-line::after {
  content: '';
  display: block;
  width: 1px;
  height: 100%;
  background-color: var(--color-bg-container-border);
}

.ds-app-sidebar__sub-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  /* The same edge inset the parent pills get; sub-items only render while
     the rail is expanded, so this needs no state selector. */
  margin-right: var(--padding-300);
  padding: var(--padding-200);
  border-radius: var(--radius-pill);
  background: transparent;
  border: none;
  color: var(--color-text-primary);
  cursor: pointer;
  flex: 1;
  text-align: left;
  overflow: hidden;
  white-space: nowrap;
  /* The row renders as an <a> when the sub-item carries an href. */
  text-decoration: none;
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-app-sidebar__sub-btn:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-app-sidebar__sub-btn--active {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-app-sidebar__sub-label {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
  white-space: nowrap;
}

/* A sub-item with children opens the side panel, and says so with a
   trailing chevron; a badge sits before it on the same right edge. */
.ds-app-sidebar__sub-label {
  flex: 1;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ds-app-sidebar__sub-btn .ds-app-sidebar__btn-badge {
  opacity: 1;
  flex-shrink: 0;
}

/* On a filled row the pill steps back to the page ground, or it would
   share the row's fill and dissolve into it. */
.ds-app-sidebar__btn--active .ds-app-sidebar__btn-badge,
.ds-app-sidebar__btn:hover .ds-app-sidebar__btn-badge,
.ds-app-sidebar__sub-btn--active .ds-app-sidebar__btn-badge,
.ds-app-sidebar__sub-btn:hover .ds-app-sidebar__btn-badge {
  background-color: var(--color-bg-page-primary);
}

.ds-app-sidebar__sub-chevron {
  --icon-size: var(--icon-size-500);
  flex-shrink: 0;
}

.ds-app-sidebar .ds-app-sidebar__sub-chevron {
  color: var(--color-icon-secondary);
}

/* The nav sections share one wrapper so the drawer's drill-in can swap
   them for the panel's level as a unit. */
.ds-app-sidebar__sections {
  display: flex;
  flex-direction: column;
  gap: var(--gap-1000);
}

/* ============================================
   CONSUMER SLOTS + BOTTOM WRAPPER
   Slots keep their height in both states so the
   rail's layout never snaps; collapsed they fade
   out and stop taking clicks.
   ============================================ */
.ds-app-sidebar__bottom {
  display: flex;
  flex-direction: column;
  gap: var(--gap-400);
  min-width: 0;
  flex-shrink: 0;
}

.ds-app-sidebar__top-slot,
.ds-app-sidebar__footer-slot {
  padding: 0 var(--padding-400);
  min-width: 0;
  overflow: hidden;
  opacity: 0;
  pointer-events: none;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-app-sidebar--expanded .ds-app-sidebar__top-slot,
.ds-app-sidebar--expanded .ds-app-sidebar__footer-slot {
  opacity: 1;
  pointer-events: auto;
}

/* ============================================
   PROFILE
   ============================================ */
.ds-app-sidebar__profile {
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-width: 0;
  /* Centres the 40px avatar in the collapsed 64px rail; glides to the
     expanded inset below. */
  padding: 0 var(--padding-300);
  flex-shrink: 0;
  transition: padding var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-app-sidebar--expanded .ds-app-sidebar__profile {
  padding: 0 var(--padding-500);
}

.ds-app-sidebar__profile-left {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}

/* The row composes Avatar at `md`, which already carries the 40px footprint,
   the pill radius, the container fill and the image/initials/glyph ladder —
   this rule only holds the seat in the row. */
.ds-app-sidebar__avatar {
  flex-shrink: 0;
}

.ds-app-sidebar__profile-info {
  display: flex;
  flex-direction: column;
  min-width: 0;
  flex-shrink: 1;
  overflow: hidden;
  opacity: 0;
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard);
}

.ds-app-sidebar--expanded .ds-app-sidebar__profile-info {
  opacity: 1;
}

.ds-app-sidebar__profile-name {
  font-family: var(--font-paragraph-emphasis-family);
  font-size: var(--font-paragraph-emphasis-size);
  font-weight: var(--font-paragraph-emphasis-weight);
  line-height: var(--font-paragraph-emphasis-line-height);
  letter-spacing: var(--font-paragraph-emphasis-letter-spacing);
  color: var(--color-text-primary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ds-app-sidebar__profile-email {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  color: var(--color-text-tertiary);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.ds-app-sidebar__profile-more {
  display: flex;
  align-items: center;
  justify-content: center;
  background: none;
  border: none;
  color: var(--color-icon-primary);
  cursor: pointer;
  padding: 0;
  flex-shrink: 0;
  width: 0;
  overflow: hidden;
  opacity: 0;
  /* Both widths are explicit (0 and 24px), so the width glides too. */
  transition: opacity var(--motion-duration-base) var(--motion-ease-standard), width var(--motion-duration-slow) var(--motion-ease-emphasized);
}

.ds-app-sidebar--expanded .ds-app-sidebar__profile-more {
  width: 24px;
  opacity: 1;
}

.ds-app-sidebar__profile-more .material-symbols-rounded {
  --icon-size: var(--icon-size-600);
}

/* ============================================
   SIDE PANEL — the SidebarPanel fixed beside the
   rail. It tracks the rail's width through the
   same slow emphasized glide, and slides a step
   out from under it on open. Hidden, it stays
   mounted (inert) so the slide can run both ways.
   ============================================ */
.ds-app-sidebar__panel {
  position: fixed;
  top: 0;
  left: 64px;
  /* One step under the rail, so the slide starts from beneath it. */
  z-index: 99;
  height: 100vh;
  border-left: var(--border-025) solid var(--color-bg-container-border);
  border-right: var(--border-025) solid var(--color-bg-container-border);
  opacity: 0;
  transform: translateX(calc(var(--padding-300) * -1));
  visibility: hidden;
  pointer-events: none;
  /* Visibility waits out the fade on the way out, then flips; on the way
     in it flips first (the --visible rule resets the delay). */
  transition:
    left var(--motion-duration-slow) var(--motion-ease-emphasized),
    opacity var(--motion-duration-base) var(--motion-ease-standard),
    transform var(--motion-duration-slow) var(--motion-ease-emphasized),
    visibility 0s linear var(--motion-duration-base);
}

.ds-app-sidebar__panel--visible {
  opacity: 1;
  transform: none;
  visibility: visible;
  pointer-events: auto;
  transition:
    left var(--motion-duration-slow) var(--motion-ease-emphasized),
    opacity var(--motion-duration-base) var(--motion-ease-standard),
    transform var(--motion-duration-slow) var(--motion-ease-emphasized),
    visibility 0s linear 0s;
}

.ds-app-sidebar__panel--panel-mode {
  left: 80px;
}

.ds-app-sidebar__panel--beside-expanded {
  left: 280px;
}

/* Floating: a second glass card beside the first, one gap along. */
.ds-app-sidebar__panel--floating {
  top: var(--ds-sidebar-float-inset, 20px);
  left: calc(var(--ds-sidebar-float-inset, 20px) + 64px + var(--gap-300));
  height: calc(100dvh - var(--ds-sidebar-float-inset, 20px) * 2);
  background-color: var(--color-bg-glass);
  border: var(--border-025) solid var(--color-bg-container-border);
  border-radius: var(--radius-600);
  box-shadow: var(--shadow-floating);
  backdrop-filter: blur(24px);
}

.ds-app-sidebar__panel--floating.ds-app-sidebar__panel--panel-mode {
  left: calc(var(--ds-sidebar-float-inset, 20px) + 80px + var(--gap-300));
}

.ds-app-sidebar__panel--floating.ds-app-sidebar__panel--beside-expanded {
  left: calc(var(--ds-sidebar-float-inset, 20px) + 280px + var(--gap-300));
}

/* ============================================
   PANEL MODE RAIL — labels under icons
   With the second level in the panel, the
   collapsed rail is the whole of level 1, so it
   widens to 80px and names every destination:
   a pill indicator behind the icon, the label
   beneath (the navigation-rail pattern).
   ============================================ */
.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) {
  width: 80px;
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__logo {
  /* Centres the 24px mark in the 80px rail: (80 - 24) / 2. */
  padding: 0 calc(var(--padding-500) + var(--padding-200));
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__nav {
  gap: 0;
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn {
  height: auto;
  margin: 0 var(--padding-100);
  /* Room between the content and the focus ring; the rows' spacing lives
     here rather than in the nav gap, so the rhythm is unchanged. */
  padding: var(--padding-100) 0;
  justify-content: center;
  border-radius: var(--radius-300);
  overflow: visible;
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn:hover,
.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn--active {
  background-color: transparent;
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn-left {
  flex-direction: column;
  gap: var(--gap-100);
  width: 100%;
}

/* The trailing chevron and count pill are faded out on any collapsed
   rail, but faded still takes width: on this centred column it pushed
   the icon and label off centre. Here they leave the layout outright. */
.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn-chevron,
.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn-badge {
  display: none;
}

/* The indicator: a 56 x 32 pill behind the icon carries hover and the
   selection, so the label stays legible on the page ground. */
.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 32px;
  border-radius: var(--radius-pill);
  transition: background-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn:hover .ds-app-sidebar__btn-icon,
.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn--active .ds-app-sidebar__btn-icon {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn-label {
  opacity: 1;
  max-width: 100%;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  letter-spacing: var(--font-caption-letter-spacing);
  text-align: center;
  text-overflow: ellipsis;
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__btn--active .ds-app-sidebar__btn-label {
  font-weight: var(--font-paragraph-sm-emphasis-weight);
}

.ds-app-sidebar--panel-mode:not(.ds-app-sidebar--expanded) .ds-app-sidebar__profile {
  /* Centres the 40px avatar in the 80px rail. */
  padding: 0 var(--padding-500);
}

.ds-app-sidebar__btn:focus-visible,
.ds-app-sidebar__sub-btn:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: -2px;
}

/* ============================================
   DRAWER DRILL-IN — the panel's level as a
   second screen inside the mobile drawer
   ============================================ */
.ds-app-sidebar__drill {
  width: auto;
  height: auto;
  padding: 0;
  background: transparent;
  animation: ds-app-sidebar-drill-in var(--motion-duration-slow) var(--motion-ease-emphasized);
}

@keyframes ds-app-sidebar-drill-in {
  from {
    opacity: 0;
    transform: translateX(var(--padding-1000));
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* ============================================
   RESPONSIVE — the mobile drawer
   Below the mobile breakpoint (768px — design.md's Breakpoints section
   is the authoritative home) the rail leaves the layout entirely and
   the fixed hamburger trigger opens it as a modal overlay drawer. The
   trigger and scrim exist only inside this media query, so the overlay
   behaviors can never activate on wider viewports.
   ============================================ */
.ds-app-sidebar__mobile-trigger {
  display: none;
}

.ds-app-sidebar__scrim {
  display: none;
}

@media (max-width: 768px) {
  .ds-app-sidebar {
    width: 0;
    padding: 0;
    overflow: hidden;
    /* Zero width still paints borders and the floating variant's glass
       edge — a hairline sliver standing where the rail was. Visibility
       hides every painted box in one property, whatever the variant;
       the open drawer below restores it. */
    visibility: hidden;
  }

  .ds-app-sidebar__panel {
    display: none;
  }

  .ds-app-sidebar__mobile-trigger {
    position: fixed;
    /* One padding step in from the corner, so hosts whose mobile
       content gutter is 16px get a trigger whose centre lines up with
       a 40px header row's. */
    top: var(--padding-400);
    left: var(--padding-400);
    z-index: 80;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    padding: 0;
    background: var(--color-bg-container-primary);
    border: var(--border-025) solid var(--color-bg-container-border);
    border-radius: var(--radius-pill);
    color: var(--color-text-primary);
    cursor: pointer;
    box-shadow: var(--shadow-floating);
  }

  .ds-app-sidebar__scrim {
    display: block;
    position: fixed;
    inset: 0;
    z-index: 90;
    background: var(--color-scrim);
  }

  /* The drawer: the full expanded rail, fixed over the scrim, sliding
     in from the left on the motion tokens (the reduced-motion guard
     zeroes the duration system-wide). */
  .ds-app-sidebar--mobile-open {
    visibility: visible;
    position: fixed;
    top: 0;
    left: 0;
    bottom: 0;
    z-index: 100;
    width: 280px;
    height: 100dvh;
    padding: var(--padding-500) 0;
    overflow-y: auto;
    background: var(--color-bg-page-primary);
    border-right: var(--border-025) solid var(--color-bg-container-border);
    box-shadow: var(--shadow-modal);
    animation: ds-app-sidebar-slide-in var(--motion-duration-base) var(--motion-ease-standard);
  }
}

@keyframes ds-app-sidebar-slide-in {
  from {
    transform: translateX(-100%);
  }
  to {
    transform: translateX(0);
  }
}

/* Icons take the colour of the text around them. Explicit, not just
   inherited by default: a consumer stylesheet that sets a colour on
   .material-symbols-rounded itself (a common global default) would
   otherwise override inheritance and detach the icon from the state
   colours this component sets on its parents.

   The two consumer slots are carved out, because inside them the rule
   does the very damage it exists to prevent: a component mounted in a
   slot sets its own icon colours through single-class selectors, and a
   two-class descendant rule outranks every one of them. A SegmentedControl
   in the footer slot lost its active segment's on-action colour that way
   and painted a black glyph on a near-black pill. :where() keeps the
   selector at its original specificity, so nothing else in the cascade
   moves. */
.ds-app-sidebar
  .material-symbols-rounded:not(:where(.ds-app-sidebar__top-slot *, .ds-app-sidebar__footer-slot *)) {
  color: inherit;
}

'use client';

import React, { useState, useCallback, useEffect, useId, useRef } from 'react';
import { useLayer } from '../../behaviors/useLayer';
import { useFocusScope } from '../../behaviors/useFocusScope';
import { useScrollLock } from '../../behaviors/useScrollLock';
import { Avatar } from '../Avatar/Avatar';
import { PixelAvatar, distinctPixelInks } from '../PixelAvatar/PixelAvatar';
import type { PixelInk } from '../PixelAvatar/PixelAvatar';
import { SidebarPanel } from '../SidebarPanel/SidebarPanel';
import type { SidebarPanelItem } from '../SidebarPanel/SidebarPanel';
import './AppSidebar.css';
import '../../fonts/material-symbols.css';

/* ============================================
   TYPES
   ============================================ */

export interface AppSidebarSubItem {
  /** Unique key for this sub-item */
  key: string;
  /** Display label */
  label: string;
  /** Click handler — also fires on a link sub-item, so a consumer can route client-side */
  onClick?: () => void;
  /** Renders the sub-item as a real link to this URL instead of a button. Ignored when the sub-item has children, whose row opens them */
  href?: string;
  /** Trailing count pill, e.g. unread items */
  badge?: string | number;
  /** Group heading this entry sits under when it is listed in the panel (see `subNav`); ignored in the accordion */
  group?: string;
  /**
   * The next level down. With `subNav="accordion"` a sub-item's children are
   * level 3 and open in the side panel; with `subNav="panel"` they are the
   * panel's own accordion. Navigation stops at three levels, so deeper
   * children are not rendered.
   */
  children?: AppSidebarSubItem[];
}

export interface AppSidebarItem {
  /** Unique key for this item */
  key: string;
  /** Item icon — Material Symbol name (string) or custom element (ReactNode). Optional only when `pixelAvatar` draws the mark instead */
  icon?: string | React.ReactNode;
  /**
   * Draws a generated PixelAvatar in the icon seat instead of `icon`, for
   * rows that name a thing rather than a place — projects, workspaces,
   * accounts. `true` seeds the character from `label`; a string seeds it
   * from that value, so a renamed item can keep its character by passing a
   * stable id. The sidebar spreads the inks across all of its avatar rows,
   * so neighbours differ in colour as well as shape. The character is
   * decorative: the label beside it is the name
   */
  pixelAvatar?: boolean | string;
  /** Display label (shown when expanded) */
  label: string;
  /** Click handler — also fires on a link item, so a consumer can route client-side */
  onClick?: () => void;
  /** Renders the item as a real link to this URL instead of a button. Ignored when the item has children, whose row is the accordion toggle */
  href?: string;
  /** Trailing count pill, e.g. unread items; hidden while the rail is collapsed */
  badge?: string | number;
  /** Sub-items: an accordion under the row, or the side panel's contents when `subNav="panel"` */
  children?: AppSidebarSubItem[];
}

export interface AppSidebarSection {
  /** Optional category label above the group */
  category?: string;
  /** Nav items in this section */
  items: AppSidebarItem[];
}

export interface AppSidebarProfile {
  /** User display name */
  name: string;
  /** User email */
  email: string;
  /** Avatar image URL */
  avatarUrl?: string;
}

export interface AppSidebarProps {
  /** Navigation sections */
  sections: AppSidebarSection[];
  /** Profile data for the bottom section */
  profile?: AppSidebarProfile;
  /** Key of the currently active item */
  activeKey?: string;
  /** Key of the currently active sub-item */
  activeSubKey?: string;
  /** Key of the currently active third-level item, listed in the side panel */
  activeTertiaryKey?: string;
  /**
   * Where an item's sub-items show. `accordion` (the default) opens them under
   * the row, and a sub-item's own children open in a side panel as level 3.
   * `panel` skips the accordion: a top-level item opens its sub-items straight
   * into the side panel, with their children as the panel's accordion, and the
   * collapsed rail shows each label under its icon. On small screens both
   * modes drill in inside the drawer instead.
   */
  subNav?: 'accordion' | 'panel';
  /** Whether the side panel starts open when there is one to show */
  defaultPanelOpen?: boolean;
  /** Controlled open state of the side panel */
  panelOpen?: boolean;
  /** Called when the side panel opens or collapses */
  onPanelOpenChange?: (open: boolean) => void;
  /** Whether sidebar starts expanded */
  defaultExpanded?: boolean;
  /** Controlled expanded state */
  expanded?: boolean;
  /** Callback when expand/collapse changes */
  onExpandedChange?: (expanded: boolean) => void;
  /** Callback when profile more button clicked */
  onProfileMore?: () => void;
  /**
   * Floats the rail off the viewport edges as a glass card: inset with
   * rounded corners, the translucent glass fill over a backdrop blur, and
   * the floating shadow. The inset defaults to 20px and is overridable via
   * the --ds-sidebar-float-inset custom property.
   */
  floating?: boolean;
  /** Rendered under the logo row, above the nav; fades out while collapsed */
  topSlot?: React.ReactNode;
  /** Rendered above the profile block; fades out while collapsed */
  footerSlot?: React.ReactNode;
  /** Additional CSS classes */
  className?: string;
  /** Logo element — defaults to the built-in brand mark */
  logo?: React.ReactNode;
  /** Text shown next to logo when expanded */
  logoText?: string;
  /**
   * Below the mobile breakpoint the rail hides and this fixed hamburger
   * button opens it as an overlay drawer instead. Set false when the
   * host renders its own trigger in the page chrome.
   */
  showMobileTrigger?: boolean;
}

/* ============================================
   INLINE LOGO SVG
   ============================================ */
function DefaultLogo() {
  return (
    <svg
      width="24"
      height="24"
      viewBox="0 0 24 24"
      fill="none"
      xmlns="http://www.w3.org/2000/svg"
      aria-hidden="true"
    >
      {/* The brand mark — a column with two outer spikes — in currentColor
          so it follows the sidebar's own text colour through both themes.
          Hand-mirrored from website/src/config/brand-mark.ts; the library
          cannot import from the website, so a change there moves here. */}
      <path d="M12 1.5 V22.5" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M6.5 7 V12 L2 16.5" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
      <path d="M17.5 7 V12 L22 16.5" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

/* ============================================
   COMPONENT
   ============================================ */

/**
 * AppSidebar — a collapsible left-hand navigation rail.
 *
 * **Collapsed** (64 px): icon-only buttons, logo mark, avatar.
 * **Expanded** (280 px): labels, category headings, accordion
 * sub-items with tree-line connectors, and a profile section.
 * A third level opens in a `SidebarPanel` beside the rail (see `subNav`).
 */
export const AppSidebar = ({
  sections,
  profile,
  activeKey,
  activeSubKey,
  activeTertiaryKey,
  subNav = 'accordion',
  defaultPanelOpen = true,
  panelOpen: controlledPanelOpen,
  onPanelOpenChange,
  defaultExpanded = false,
  expanded: controlledExpanded,
  onExpandedChange,
  onProfileMore,
  floating = false,
  topSlot,
  footerSlot,
  className = '',
  logo,
  logoText = 'Rift',
  showMobileTrigger = true,
}: AppSidebarProps) => {
  const baseClass = 'ds-app-sidebar';

  /* The avatar rows' inks, spread across the whole sidebar so neighbours
     differ in colour as well as shape. */
  const avatarSeed = (item: AppSidebarItem) =>
    typeof item.pixelAvatar === 'string' ? item.pixelAvatar : item.label;
  const avatarItems = sections.flatMap((section) =>
    section.items.filter((item) => item.pixelAvatar),
  );
  const avatarInks = new Map<string, PixelInk>();
  distinctPixelInks(avatarItems.map(avatarSeed)).forEach((ink, index) => {
    avatarInks.set(avatarItems[index].key, ink);
  });

  /* Expand / collapse */
  const [internalExpanded, setInternalExpanded] = useState(defaultExpanded);
  const isExpanded = controlledExpanded ?? internalExpanded;
  const onExpandedChangeRef = useRef(onExpandedChange);
  useEffect(() => {
    onExpandedChangeRef.current = onExpandedChange;
  }, [onExpandedChange]);

  const toggleExpanded = useCallback(() => {
    const next = !isExpanded;
    setInternalExpanded(next);
    onExpandedChange?.(next);
  }, [isExpanded, onExpandedChange]);

  /* Tablet band (769-959px): the expanded rail is a third of the
     viewport, so entering the band folds it to the icon rail once —
     through the same path a click takes, so controlled hosts hear it.
     Deliberately entry-only: the visitor can re-expand by hand. */
  useEffect(() => {
    const band = window.matchMedia('(min-width: 769px) and (max-width: 959px)');
    const onChange = () => {
      if (band.matches) {
        setInternalExpanded(false);
        onExpandedChangeRef.current?.(false);
      }
    };
    onChange();
    band.addEventListener('change', onChange);
    return () => band.removeEventListener('change', onChange);
  }, []);

  /* Mobile drawer: below the breakpoint the rail is hidden and the
     trigger opens it as a modal overlay, on the shared behavior layer
     like every other overlay (dismissal stack, focus trap, scroll
     lock). The trigger is CSS-gated to the mobile media query, so the
     overlay can only ever activate there; crossing back up while open
     closes it, or the scroll lock would outlive the drawer. */
  const [mobileOpen, setMobileOpen] = useState(false);
  const drawerRef = useRef<HTMLElement>(null);
  const drawerId = useId();
  const closeMobile = useCallback(() => setMobileOpen(false), []);
  useLayer({ open: mobileOpen, onDismiss: closeMobile });
  useFocusScope(drawerRef, { active: mobileOpen });
  useScrollLock(mobileOpen);
  useEffect(() => {
    if (!mobileOpen) return;
    const query = window.matchMedia('(min-width: 769px)');
    const onChange = () => {
      if (query.matches) setMobileOpen(false);
    };
    onChange();
    query.addEventListener('change', onChange);
    return () => query.removeEventListener('change', onChange);
  }, [mobileOpen]);

  /* Accordion open keys. The accordion holding the current page starts
     open, so a three-level path is visible from the first render. */
  const [openKeys, setOpenKeys] = useState<Set<string>>(() => {
    const initial = new Set<string>();
    if (subNav !== 'panel' && (activeSubKey || activeTertiaryKey)) {
      for (const section of sections) {
        for (const item of section.items) {
          const holdsActive = item.children?.some(
            (sub) =>
              sub.key === activeSubKey ||
              sub.children?.some((leaf) => leaf.key === activeTertiaryKey),
          );
          if (holdsActive) initial.add(item.key);
        }
      }
    }
    return initial;
  });

  const toggleAccordion = useCallback((key: string) => {
    setOpenKeys((prev) => {
      const next = new Set(prev);
      if (next.has(key)) {
        next.delete(key);
      } else {
        next.add(key);
      }
      return next;
    });
  }, []);

  /* ---- Side panel (the level below the accordion, or the whole
     second level when subNav is 'panel') ----
     The panel's source is the row whose children it lists: a sub-item in
     accordion mode, a top-level item in panel mode. It starts on the row
     holding the current page, and a click on any row with children moves
     it there. */
  const isPanelMode = subNav === 'panel';
  const [panelSourceKey, setPanelSourceKey] = useState<string | undefined>(() => {
    for (const section of sections) {
      for (const item of section.items) {
        if (isPanelMode) {
          if (
            item.children?.length &&
            (item.key === activeKey || item.children.some((c) => c.key === activeSubKey))
          ) {
            return item.key;
          }
        } else {
          for (const sub of item.children ?? []) {
            if (
              sub.children?.length &&
              (sub.key === activeSubKey || sub.children.some((c) => c.key === activeTertiaryKey))
            ) {
              return sub.key;
            }
          }
        }
      }
    }
    return undefined;
  });

  /* Resolve the source to what the panel shows. Accordion mode passes the
     sub-item's children without their own children: three levels is the
     cap, so a fourth never renders. */
  let panelSource: { label: string; parentLabel?: string; items: SidebarPanelItem[] } | undefined;
  for (const section of sections) {
    for (const item of section.items) {
      if (isPanelMode && item.key === panelSourceKey && item.children?.length) {
        panelSource = { label: item.label, items: item.children };
      }
      if (!isPanelMode) {
        for (const sub of item.children ?? []) {
          if (sub.key === panelSourceKey && sub.children?.length) {
            panelSource = {
              label: sub.label,
              parentLabel: item.label,
              items: sub.children.map(({ children: _deeper, ...leaf }) => leaf),
            };
          }
        }
      }
    }
  }

  const [internalPanelOpen, setInternalPanelOpen] = useState(defaultPanelOpen);
  const isPanelOpen = controlledPanelOpen ?? internalPanelOpen;
  const setPanelOpen = useCallback(
    (next: boolean) => {
      setInternalPanelOpen(next);
      if (next !== isPanelOpen) onPanelOpenChange?.(next);
    },
    [isPanelOpen, onPanelOpenChange],
  );
  const panelVisible = Boolean(panelSource) && isPanelOpen;
  const panelId = useId();

  /* In the drawer the panel's level is a second screen: a row with
     children drills in, the back row returns. Opening the drawer lands on
     the screen holding the current page. */
  const [drilled, setDrilled] = useState(false);
  const focusAfterDrill = useRef<'in' | 'out' | null>(null);
  const openMobile = useCallback(() => {
    setDrilled(Boolean(panelSource));
    setMobileOpen(true);
  }, [panelSource]);
  useEffect(() => {
    const target = focusAfterDrill.current;
    focusAfterDrill.current = null;
    if (!target || !drawerRef.current) return;
    const selector =
      target === 'in' ? '.ds-sidebar-panel__back' : '[data-panel-source="true"]';
    drawerRef.current.querySelector<HTMLElement>(selector)?.focus();
  }, [drilled]);

  /** A row with children that feeds the panel was pressed. */
  const selectPanelSource = useCallback(
    (key: string) => {
      if (mobileOpen) {
        setPanelSourceKey(key);
        focusAfterDrill.current = 'in';
        setDrilled(true);
        return;
      }
      if (key === panelSourceKey && isPanelOpen) {
        setPanelOpen(false);
      } else {
        setPanelSourceKey(key);
        setPanelOpen(true);
      }
    },
    [mobileOpen, panelSourceKey, isPanelOpen, setPanelOpen],
  );

  const classes = [
    baseClass,
    // The drawer always shows the expanded layout: an icon rail inside
    // a modal overlay would be all cost and no labels.
    isExpanded || mobileOpen ? `${baseClass}--expanded` : '',
    floating ? `${baseClass}--floating` : '',
    mobileOpen ? `${baseClass}--mobile-open` : '',
    isPanelMode ? `${baseClass}--panel-mode` : '',
    className,
  ]
    .filter(Boolean)
    .join(' ');

  return (
    <>
      {showMobileTrigger && (
        <button
          type="button"
          className={`${baseClass}__mobile-trigger`}
          aria-label="Open navigation"
          aria-expanded={mobileOpen}
          aria-controls={drawerId}
          onClick={openMobile}
        >
          <span className="material-symbols-rounded" aria-hidden="true">
            menu
          </span>
        </button>
      )}
      {mobileOpen && (
        <div className={`${baseClass}__scrim`} onClick={closeMobile} aria-hidden="true" />
      )}
    <nav ref={drawerRef} id={drawerId} className={classes} aria-label="App navigation">
      {/* ---- TOP ---- */}
      <div className={`${baseClass}__top`}>
        {/* Logo */}
        <div className={`${baseClass}__logo`}>
          <div
            className={`${baseClass}__logo-inner`}
            onClick={!isExpanded ? toggleExpanded : undefined}
            role={!isExpanded ? 'button' : undefined}
            tabIndex={!isExpanded ? 0 : undefined}
            aria-label={!isExpanded ? 'Expand sidebar' : undefined}
            onKeyDown={!isExpanded ? (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); toggleExpanded(); } } : undefined}
            style={!isExpanded ? { cursor: 'pointer' } : undefined}
          >
            <span className={`${baseClass}__logo-icon`}>
              {logo || <DefaultLogo />}
            </span>
            <span className={`${baseClass}__logo-text`}>{logoText}</span>
          </div>
          {/* In the mobile drawer the rail has nothing to collapse to, so
              the same button becomes the drawer's close control. Driven by
              `mobileOpen` rather than a media query: the flag can only be
              true below the breakpoint, so the two never disagree. */}
          <button
            className={`${baseClass}__toggle`}
            onClick={mobileOpen ? closeMobile : toggleExpanded}
            aria-label={
              mobileOpen
                ? 'Close navigation'
                : isExpanded
                  ? 'Collapse sidebar'
                  : 'Expand sidebar'
            }
          >
            <span className="material-symbols-rounded">
              {mobileOpen ? 'close' : isExpanded ? 'left_panel_close' : 'left_panel_open'}
            </span>
          </button>
        </div>

        {/* Consumer slot under the logo row */}
        {topSlot && <div className={`${baseClass}__top-slot`}>{topSlot}</div>}

        {/* Drawer drill-in: the panel's level as a second screen */}
        {mobileOpen && drilled && panelSource ? (
          <SidebarPanel
            key={panelSourceKey}
            className={`${baseClass}__drill`}
            items={panelSource.items}
            title={panelSource.label}
            activeKey={activeTertiaryKey ?? activeSubKey}
            onBack={() => {
              focusAfterDrill.current = 'out';
              setDrilled(false);
            }}
            backLabel={panelSource.parentLabel ?? 'Menu'}
          />
        ) : (
        <div className={`${baseClass}__sections`}>
        {/* Nav sections */}
        {sections.map((section, si) => (
          <div key={si} className={`${baseClass}__nav`}>
            {section.category && (
              <div className={`${baseClass}__category`}>{section.category}</div>
            )}

            {section.items.map((item) => {
              const hasChildren = item.children && item.children.length > 0;
              const isOpen = openKeys.has(item.key);
              /* Panel mode: the row feeding a visible panel carries the
                 selection, so the rail shows which section is open. */
              const feedsPanel = isPanelMode && hasChildren;
              const isSource = feedsPanel && item.key === panelSourceKey;
              const isActive =
                isPanelMode && panelVisible ? isSource : activeKey === item.key;

              /* A leaf item with an href is a real link; an accordion row
                 stays a button whatever it declares, because its job is to
                 toggle, not navigate. */
              const isLink = Boolean(item.href) && !hasChildren;

              const itemClasses = [
                `${baseClass}__btn`,
                isActive ? `${baseClass}__btn--active` : '',
              ]
                .filter(Boolean)
                .join(' ');

              const itemContent = (
                <>
                  <span className={`${baseClass}__btn-left`}>
                    {item.pixelAvatar ? (
                      <span className={`${baseClass}__btn-icon ${baseClass}__btn-icon--avatar`}>
                        <PixelAvatar name={avatarSeed(item)} ink={avatarInks.get(item.key)} />
                      </span>
                    ) : (
                      <span
                        className={`${baseClass}__btn-icon${typeof item.icon === 'string' ? ' material-symbols-rounded' : ''}`}
                      >
                        {item.icon}
                      </span>
                    )}
                    <span className={`${baseClass}__btn-label`}>{item.label}</span>
                  </span>
                  {item.badge !== undefined && (
                    <span className={`${baseClass}__btn-badge`}>{item.badge}</span>
                  )}
                  {/* Accordion rows turn the chevron down when open; a row
                      feeding the panel points it at the panel and holds. */}
                  {hasChildren && (
                    <span
                      className={[
                        `${baseClass}__btn-chevron material-symbols-rounded`,
                        isOpen && !isPanelMode ? `${baseClass}__btn-chevron--open` : '',
                      ]
                        .filter(Boolean)
                        .join(' ')}
                    >
                      chevron_right
                    </span>
                  )}
                </>
              );

              return (
                <React.Fragment key={item.key}>
                  {isLink ? (
                    <a
                      className={itemClasses}
                      href={item.href}
                      onClick={() => item.onClick?.()}
                      aria-current={isActive ? 'page' : undefined}
                      title={!isExpanded ? item.label : undefined}
                    >
                      {itemContent}
                    </a>
                  ) : (
                    <button
                      type="button"
                      className={itemClasses}
                      onClick={() => {
                        if (feedsPanel) {
                          selectPanelSource(item.key);
                        } else if (hasChildren) {
                          /* On the collapsed rail the accordion has nowhere
                             to open, so the row expands the rail first. */
                          if (!isExpanded && !mobileOpen) {
                            toggleExpanded();
                            setOpenKeys((prev) => new Set(prev).add(item.key));
                          } else {
                            toggleAccordion(item.key);
                          }
                        }
                        item.onClick?.();
                      }}
                      aria-expanded={
                        feedsPanel
                          ? mobileOpen
                            ? undefined
                            : isSource && panelVisible
                          : hasChildren
                            ? isOpen
                            : undefined
                      }
                      aria-controls={feedsPanel && !mobileOpen ? panelId : undefined}
                      aria-current={activeKey === item.key ? 'page' : undefined}
                      data-panel-source={isSource ? 'true' : undefined}
                      title={!isExpanded && !isPanelMode ? item.label : undefined}
                    >
                      {itemContent}
                    </button>
                  )}

                  {/* Sub-items */}
                  {hasChildren && !isPanelMode && (
                    <div
                      className={[
                        `${baseClass}__sub-items`,
                        isOpen && isExpanded ? `${baseClass}__sub-items--open` : '',
                      ]
                        .filter(Boolean)
                        .join(' ')}
                    >
                      {item.children!.map((sub) => {
                        const subHasChildren = Boolean(sub.children?.length);
                        const subIsSource = subHasChildren && sub.key === panelSourceKey;
                        const subActive = panelVisible && subHasChildren
                          ? subIsSource
                          : activeSubKey === sub.key;
                        const subClasses = [
                          `${baseClass}__sub-btn`,
                          subActive ? `${baseClass}__sub-btn--active` : '',
                        ]
                          .filter(Boolean)
                          .join(' ');
                        const subLabel = (
                          <>
                            <span className={`${baseClass}__sub-label`}>{sub.label}</span>
                            {sub.badge !== undefined && (
                              <span className={`${baseClass}__btn-badge`}>{sub.badge}</span>
                            )}
                            {subHasChildren && (
                              <span
                                className={`${baseClass}__sub-chevron material-symbols-rounded`}
                                aria-hidden="true"
                              >
                                chevron_right
                              </span>
                            )}
                          </>
                        );
                        return (
                          <div key={sub.key} className={`${baseClass}__sub-item`}>
                            <div className={`${baseClass}__sub-line`} />
                            {subHasChildren ? (
                              <button
                                type="button"
                                className={subClasses}
                                onClick={() => {
                                  selectPanelSource(sub.key);
                                  sub.onClick?.();
                                }}
                                aria-expanded={mobileOpen ? undefined : subIsSource && panelVisible}
                                aria-controls={mobileOpen ? undefined : panelId}
                                aria-current={activeSubKey === sub.key ? 'page' : undefined}
                                data-panel-source={subIsSource ? 'true' : undefined}
                              >
                                {subLabel}
                              </button>
                            ) : sub.href ? (
                              <a
                                className={subClasses}
                                href={sub.href}
                                onClick={sub.onClick}
                                aria-current={subActive ? 'page' : undefined}
                              >
                                {subLabel}
                              </a>
                            ) : (
                              <button
                                type="button"
                                className={subClasses}
                                onClick={sub.onClick}
                                aria-current={subActive ? 'page' : undefined}
                              >
                                {subLabel}
                              </button>
                            )}
                          </div>
                        );
                      })}
                    </div>
                  )}
                </React.Fragment>
              );
            })}
          </div>
        ))}
        </div>
        )}
      </div>

      {/* ---- BOTTOM — consumer slot + profile ---- */}
      <div className={`${baseClass}__bottom`}>
        {footerSlot && (
          <div className={`${baseClass}__footer-slot`}>{footerSlot}</div>
        )}
        {profile && (
        <div className={`${baseClass}__profile`}>
          <div className={`${baseClass}__profile-left`}>
            {/* Avatar owns the fallback ladder: the picture when there is
                one, the person's initials when there is not, and the generic
                glyph when there is neither. The hand-rolled box this replaced
                drew an empty disc for every profile with no avatarUrl. */}
            <Avatar
              className={`${baseClass}__avatar`}
              size="md"
              name={profile.name}
              src={profile.avatarUrl}
            />
            <div className={`${baseClass}__profile-info`}>
              <span className={`${baseClass}__profile-name`}>{profile.name}</span>
              <span className={`${baseClass}__profile-email`}>{profile.email}</span>
            </div>
          </div>
          <button
            className={`${baseClass}__profile-more`}
            onClick={onProfileMore}
            aria-label="Profile options"
          >
            <span className="material-symbols-rounded">more_horiz</span>
          </button>
        </div>
        )}
      </div>
    </nav>
      {/* The side panel, fixed beside the rail. Kept mounted while it has a
          source so it can slide; inert while hidden. CSS keeps it off small
          screens, where the drawer's drill-in shows the same level. */}
      {panelSource && !mobileOpen && (
        <SidebarPanel
          key={panelSourceKey}
          id={panelId}
          className={[
            `${baseClass}__panel`,
            panelVisible ? `${baseClass}__panel--visible` : '',
            isExpanded ? `${baseClass}__panel--beside-expanded` : '',
            isPanelMode ? `${baseClass}__panel--panel-mode` : '',
            floating ? `${baseClass}__panel--floating` : '',
          ]
            .filter(Boolean)
            .join(' ')}
          items={panelSource.items}
          title={panelSource.label}
          activeKey={activeTertiaryKey ?? activeSubKey}
          onCollapse={() => setPanelOpen(false)}
          inert={!panelVisible}
        />
      )}
    </>
  );
};
